return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Italian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 18:00+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'it_IT','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Routing multilingue, meta tag SEO e strumenti di contenuto AI per WordPress. Combina rilevamento della lingua, routing URL, hreflang, meta descrizioni e funzionalità AI per estratti, meta e traduzioni.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Traduci','Lingua Forge — Quick Translate'=>'Lingua Forge — Traduzione rapida','Informative'=>'Informativo','Persuasive'=>'Persuasivo','Storytelling'=>'Storytelling','Technical'=>'Tecnico','Conversational'=>'Conversazionale','Permission denied.'=>'Permesso negato.','Cannot determine target language from slug.'=>'Impossibile determinare la lingua di destinazione dallo slug.','Invalid post type.'=>'Tipo di post non valido.','Invalid or primary language.'=>'Lingua non valida o primaria.','Template not found or not stored in the database.'=>'Modello non trovato o non memorizzato nel database.','Template has no content.'=>'Il modello non ha contenuto.','No internal links found to update.'=>'Nessun collegamento interno trovato da aggiornare.','%d link updated.'=>'%d collegamento aggiornato.' . "\0" . '%d collegamenti aggiornati.','No language-specific template parts found to map.'=>'Nessuna parte del modello specifica della lingua trovata da mappare.','No template part references needed updating.'=>'Nessun riferimento alla parte del modello da aggiornare.','%d part reference updated.'=>'%d riferimento alla parte aggiornato.' . "\0" . '%d riferimenti alle parti del modello aggiornati.','Invalid language.'=>'Lingua non valida.','Template part not found or not stored in the database.'=>'Parte del modello non trovata o non memorizzata nel database.','Template part has no content.'=>'La parte del modello non ha contenuto.','No navigation references needed updating.'=>'Nessun riferimento di navigazione da aggiornare.','%d navigation reference updated.'=>'%d riferimento di navigazione aggiornato.' . "\0" . '%d riferimenti di navigazione aggiornati.','No AI provider configured.'=>'Nessun provider AI configurato.','Missing pattern name or language.'=>'Nome del pattern o lingua mancanti.','Pattern not found.'=>'Pattern non trovato.','Pattern has no content to translate.'=>'Il pattern non ha contenuto da tradurre.','AI provider returned an empty response.'=>'Il provider AI ha restituito una risposta vuota.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Pattern tradotto e salvato. Copia il contenuto nel tuo post CPT tramite l\'inseritore di pattern dell\'editor a blocchi o usalo come punto di partenza per un blocco riutilizzabile.','Invalid template type.'=>'Tipo di modello non valido.','Template "%s" already exists.'=>'Il modello "%s" esiste già.','"%s" created.'=>'"%s" creato.','Invalid template part.'=>'Parte del modello non valida.','Template part "%s" already exists.'=>'Parte del modello "%s" esiste già.','"%1$s" created. %2$d template updated.'=>'"%1$s" creato. %2$d modello aggiornato.' . "\0" . '"%1$s" creato. %2$d modelli aggiornati.','Page'=>'Pagina','Single'=>'Singolo','Search'=>'Ricerca','Search Results'=>'Risultati di ricerca','Archive'=>'Archivio','Front Page'=>'Pagina principale','Single: %s'=>'Singolo: %s','Single %s'=>'Singolo %s','Archive: %s'=>'Archivio: %s','%s Archive'=>'%s Archivio','No source content found to translate.'=>'Nessun contenuto di origine trovato da tradurre.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Tradotto. Rivedi nell\'Editor del sito — i link interni, gli URL di navigazione e gli slug dei template non vengono aggiornati automaticamente.','Navigation not found.'=>'Navigazione non trovata.','Navigation has no content to translate.'=>'La navigazione non ha contenuto da tradurre.','"%1$s %2$s" saved.'=>'"%1$s %2$s" salvato.','Translate page…'=>'Traduci pagina…','Generate content…'=>'Genera contenuto…','AI Behaviour Preset'=>'Preset di comportamento AI','Custom'=>'Personalizzato','Global default (%s)'=>'Predefinito globale (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>' Sovrascrive il preset AI per Traduzione e Generazione di contenuti su questa pagina. Le istruzioni personalizzate a livello di sito (Impostazioni → Comportamento) vengono sempre aggiunte a ogni richiesta indipendentemente da questa selezione.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sovrascrive il preset AI per Traduzione e Generazione di contenuti su questa pagina. Tutte le altre funzionalità usano sempre il preset globale.','Close'=>'Chiudi','Translate missing'=>'Traduzione mancante','From'=>'Da','Retranslate'=>'Retraduci','Translating…'=>'Traduzione in corso…','Retranslating…'=>'Retraduzione in corso…','✓ Done'=>'✓ Fatto','Error'=>'Errore','Navigation posts are translated via the Router tab, not this button.'=>'I post di navigazione vengono tradotti tramite la scheda Router, non con questo pulsante.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'La creazione di traduzioni per il tipo di post "%s" richiede un\'integrazione attiva. Assicurati che l\'integrazione richiesta sia installata e attiva.','No %s version found in this translation group.'=>'Nessuna versione %s trovata in questo gruppo di traduzioni.','AI Usage'=>'Utilizzo AI','Today'=>'Oggi','Last 7 days'=>'Ultimi 7 giorni','Last 30 days'=>'Ultimi 30 giorni','All time'=>'Tutto il tempo','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Consumo di token aggregato per funzionalità, provider e modello. Registrato ad ogni chiamata AI riuscita; i ping di Test Connection sono deliberatamente esclusi per non distorcere i totali. La tabella sottostante aggrega i dati giornalieri — scegli una finestra qui sotto per visualizzarla.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Nessun utilizzo di AI registrato finora. Una volta che un editor esegue una traduzione, genera una meta descrizione o utilizza qualsiasi altra funzionalità AI, i totali appariranno qui.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nessun utilizzo di AI registrato nella finestra selezionata (%s). Scegli un intervallo più ampio sopra.','Feature'=>'Funzionalità','Provider'=>'Provider','Model'=>'Modello','Requests'=>'Richieste','Input tokens'=>'Token di input','Output tokens'=>'Token di output','Total tokens'=>'Token totali','Total'=>'Totale','API Keys'=>'Chiavi API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Le chiavi sono criptate con AES-256-CBC prima di essere memorizzate nel database di WordPress. Il segreto di crittografia deriva dai sali di autenticazione di WordPress (wp-config.php), quindi le chiavi in testo semplice non vengono mai toccate dal database.','API Key'=>'Chiave API','Paste your API key…'=>'Incolla la tua chiave API…','✓ Configured'=>'✓ Configurato','✗ Not configured'=>'✗ Non configurato','Test connection'=>'Testa la connessione','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lascia vuoto per mantenere la chiave esistente. Inserisci un nuovo valore per sostituirla.','Remove stored key'=>'Rimuovi chiave memorizzata','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Questa chiave è attualmente fornita da un server %s e non può essere rimossa qui. Inserisci una nuova chiave sopra per sovrascriverla con un valore del database.','environment variable'=>'variabile d\'ambiente','PHP constant'=>'costante PHP','Alternative (server-side):'=>'Alternativa (lato server):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Puoi anche definire le chiavi come costanti o variabili d\'ambiente (ad esempio in wp-config.php). Queste fonti vengono utilizzate automaticamente come fallback quando nessuna chiave del database è memorizzata.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Per usare un segreto di crittografia personalizzato (invece del valore derivato wp_salt), aggiungi questo a wp-config.php:','Unknown provider.'=>'Provider sconosciuto.','No API key configured for this provider.'=>'Nessuna chiave API configurata per questo provider.','Could not instantiate the provider.'=>'Impossibile istanziare il provider.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Il provider non ha restituito testo. Controlla il registro errori di WordPress per il motivo dettagliato del fallimento.','Behavior'=>'Comportamento','Block Editor'=>'Editor a blocchi','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge limita di default due funzionalità di Gutenberg per mantenere coerente il comportamento editoriale tra le lingue. Attiva qui se hai bisogno di tutte le capacità di Gutenberg / FSE.','Block locking'=>'Blocco di blocco','Allow editors to lock individual blocks'=>'Consenti agli editor di bloccare blocchi individuali','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Riabilita canLockBlocks di Gutenberg. Utile per modelli editoriali che devono impedire ai collaboratori di spostare o eliminare blocchi specifici.','Template mode'=>'Modalità modello','Allow Gutenberg template-editing mode on post screens'=>'Consenti la modalità di modifica modello di Gutenberg nelle schermate dei post','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Riabilita supportsTemplateMode. Fondamentale per i flussi di lavoro di Full-Site-Editing in cui le override di modello a livello di post sono intenzionali.','Compliance Preset'=>'Predefinito di conformità','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modalità di conservazione rigorosa per contenuti legali, regolamentari, medici o tecnici. Quando attivo, ogni funzionalità AI utilizza una temperatura di campionamento bassa e aggiunge il supplemento sotto al suo prompt di sistema — terminologia, numeri di articolo, unità, nomi di marca e linguaggio regolamentare sono preservati letteralmente anziché parafrasati.','Global AI preset'=>'Predefinito AI globale','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per funzionalità','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Imposta il comportamento predefinito di AI per tutte le funzionalità nel sito. I singoli post possono sovrascrivere questo per Traduzione e Generazione di contenuti tramite la meta box di Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard utilizza la temperatura ottimizzata di ogni funzionalità: Traduzione T=0.2 (preciso), Traduzione rapida T=0.4, Generatore di contenuti T=0.6 (creativo). Gli altri preset applicano una temperatura fissa unica a tutte le funzionalità.','Technical / Scientific instructions'=>'Istruzioni tecniche / scientifiche','Legal / Compliance instructions'=>'Istruzioni legali / di conformità','Creative / Marketing instructions'=>'Istruzioni creative / di marketing','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lascia vuoto per usare il valore predefinito integrato. Cancellare una sovrascrittura salvata ripristina il default al prossimo salvataggio.','View built-in default'=>'Visualizza default integrato','Translation Memory'=>'Memoria di traduzione','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Memorizza in cache gli equivalenti tradotti a livello di blocco in modo che i contenuti riutilizzabili (footer condivisi, barre laterali, accordioni, sezioni legali con molte formule) non paghino una chiamata API ogni volta. Quando abilitato, il flusso di traduzione analizza ogni post in blocchi, cerca ogni blocco nella cache e invia solo i blocchi non memorizzati in cache all\'AI in una richiesta batch. Le modifiche al glossario e le modifiche al preset di conformità invalidano automaticamente le traduzioni memorizzate nella cache interessate. Visualizza statistiche e cancella la cache sotto Manutenzione.','Enable block-level translation cache reuse across posts'=>'Riutilizzo della cache di traduzione a livello di blocco tra i post','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Attualmente saltato per i post che usano segnaposto di attributo commento-blocco (wp:details campi di riepilogo, ecc.) — passano alla normale traduzione con chiamata singola.','General'=>'Generale','Light'=>'Leggero','Meta Description, Excerpt Generator'=>'Meta Descrizione, Generatore di estratti','Quality'=>'Qualità','Translation, Content Generator'=>'Traduzione, Generatore di contenuti','Active Provider'=>'Provider attivo','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Attualmente ereditato dalla costante %s. Selezionare un valore qui lo sovrascriverà.','Models'=>'Modelli','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Le funzionalità sono raggruppate in due livelli. Inserisci l\'identificatore esatto del modello per ogni livello e provider. Lascia vuoto per usare il default integrato (mostrato come segnaposto). Solo i modelli del provider attivo vengono chiamati in fase di esecuzione — configura gli altri in anticipo se prevedi di cambiare.','active'=>'attivo','overridden'=>'sovrascritto','Tip: to reset a model to the built-in default, clear the field and save.'=>'Suggerimento: per ripristinare un modello al default integrato, cancella il campo e salva.','Glossary'=>'Glossario','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabella terminologica gestita dall\'utente per coppia di lingue. Le voci vengono aggiunte al prompt del sistema di traduzione affinché l\'IA utilizzi termini preferiti in modo coerente — fondamentale per il vocabolario di dominio ("kWp", "PPA", "punto di interconnessione"), nomi di marca che non devono essere tradotti e formulazioni normative standardizzate. Entrambi i campi della lingua sono opzionali: lasciare vuoto "Lingua di origine" per applicare la voce indipendentemente dalla lingua da cui si traduce; lasciare vuoto "Lingua di destinazione" per applicarla a tutte le lingue di destinazione contemporaneamente.','Glossary entry added.'=>'Voce del glossario aggiunta.','Glossary entry removed.'=>'Voce del glossario rimossa.','Could not add entry: source term and target term are required.'=>'Impossibile aggiungere la voce: sono necessari il termine di origine e quello di destinazione.','Could not save the glossary entry.'=>'Impossibile salvare la voce del glossario.','Source language'=>'Lingua di origine','— Any —'=>'— Qualsiasi —','Target language'=>'Lingua di destinazione','— Any target —'=>'— Qualsiasi destinazione —','Filter'=>'Filtro','Reset'=>'Reimposta','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Nessuna voce del glossario corrisponde al filtro attuale. Rimuovi il filtro per visualizzare tutte le voci o aggiungi una nuova voce qui sotto.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Ancora nessuna voce del glossario. Aggiungine una sotto per iniziare a applicare la terminologia nelle traduzioni.','Source term'=>'Termine di origine','Target term'=>'Termine di destinazione','Source lang'=>'Lingua di origine','Target lang'=>'Lingua di destinazione','Notes'=>'Note','any'=>'qualsiasi','Delete this glossary entry?'=>'Eliminare questa voce del glossario?','Delete'=>'Elimina','Add new entry'=>'Aggiungi nuova voce','The phrase as it appears in the source text.'=>'La frase così come appare nel testo di origine.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Come dovrebbe apparire nella traduzione. Digita lo stesso valore del termine di origine per istruire l\'IA a conservarlo letteralmente.','— Any source language —'=>'— Qualsiasi lingua di origine —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lascia vuoto per nomi di marca e termini indipendenti dalla lingua che devono essere mantenuti invariati indipendentemente dalla lingua di origine.','— Any target language —'=>'— Qualsiasi lingua di destinazione —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lascia vuoto per applicare questa voce a tutte le lingue di destinazione — ideale per nomi di marca, abbreviazioni e termini che devono essere preservati letteralmente in ogni traduzione.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contesto opzionale per gli editor (ad esempio "ASIC = Circuito integrato specifico per applicazione; da conservare in inglese in contesti tecnici").','Add entry'=>'Aggiungi voce','Limits'=>'Limiti','Authors and above (edit_published_posts)'=>'Autori e superiori (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Contributori e superiori — predefinito (edit_posts)','Editors and above (edit_others_posts)'=>'Editor e superiori (edit_others_posts)','Administrators only (manage_options)'=>'Solo amministratori (manage_options)','AI Limits & Security'=>'Limiti e sicurezza dell\'IA','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita l\'uso dell\'IA che il sito può generare e restringe quali ruoli utente possono attivare chiamate IA a pagamento. Si sovrappone al limite di richiesta per utente (30 richieste / minuto, hardcoded) che già protegge da loop incontrollati di singoli utenti.','Daily request limit'=>'Limite giornaliero di richieste','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Limite massimo di richieste IA per giorno UTC (include sia le traduzioni della toolbar che le revisioni dei blocchi). Il contatore si resetta a mezzanotte UTC. Imposta a 0 per disabilitare il limite.','Minimum role'=>'Ruolo minimo','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'La capacità di WordPress più bassa consentita per attivare le funzioni IA. Ristretta su siti multi-autore per impedire a Contributori o account di prova di eseguire chiamate IA a pagamento. Sovrascrivi per funzione tramite il filtro linguaforge_required_capability.','Translation Limits'=>'Limiti di traduzione','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controlla quanto contenuto viene inviato all\'IA e quanto può essere grande la risposta. Lascia vuoto per usare il valore predefinito integrato (mostrato come segnaposto). Aumenta questi valori se le pagine grandi vengono tagliate; riducili per ridurre i costi API.','Model tier'=>'Livello del modello','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualità (predefinito — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Leggero (veloce ed economico — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Quale livello di modello usare per la traduzione di pagine complete. La qualità utilizza il modello configurato nella tabella Modelli sopra ed è raccomandata per traduzioni accurate e di lunga durata. Passa a Leggero solo se la velocità o il costo sono prioritari e il contenuto è breve.','Max output tokens'=>'Token di output massimo','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Numero massimo di token che l\'IA può produrre in una singola risposta di traduzione. Se una traduzione viene tagliata silenziosamente alla fine, aumenta questo valore. Predefinito: 16.000.','Max input characters'=>'Caratteri di input massimi','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Numero massimo di caratteri del contenuto del post inoltrato all\'IA. 0 significa nessun limite — il contenuto completo viene sempre inviato (consigliato). Imposta un valore diverso da zero solo se il tuo provider ha una finestra di contesto ristretta. Viene scritto un avviso nel registro degli errori PHP ogni volta che il contenuto viene troncato.','Quick Translation'=>'Traduzione rapida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traduzione rapida viene utilizzata in modalità snippet/pezzo — brevi passaggi tradotti su richiesta dalla barra degli strumenti, editor o popover dei blocchi. Utilizza una configurazione separata e più leggera rispetto alla traduzione a pagina intera per mantenere le risposte rapide e convenienti.','Light (default — fast and cost-effective)'=>'Leggero (predefinito — rapido ed economico)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualità (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Il livello Light utilizza il modello rapido configurato nella tabella Modelli sopra (predefinito: Haiku / Flash). Passa a Qualità se hai bisogno della stessa precisione di traduzione della modalità a pagina intera per gli snippet.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Token massimi che l\'IA può produrre per ogni traduzione rapida. Predefinito: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Caratteri massimi accettati dal campo di input. Predefinito: 8.000.','Content Generator'=>'Generatore di contenuti','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controlla il budget di token e i limiti di input per la funzione Generatore di contenuti AI. Lascia i campi vuoti per usare i valori predefiniti integrati.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Token massimi che l\'IA può produrre per ogni esecuzione di generazione. Aumenta questo limite se gli articoli completi vengono tagliati. Predefinito: 8.192.','Max hints characters'=>'Caratteri massimi per suggerimenti','Maximum characters read from the Hints field. Default: 2 000.'=>'Caratteri massimi letti dal campo Suggerimenti. Predefinito: 2.000.','Max context characters'=>'Caratteri di contesto massimi','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Caratteri massimi del contenuto del post esistente passati all\'IA come contesto seme quando non vengono forniti Suggerimenti. Predefinito: 6.000.','Maintenance'=>'Manutenzione','Language Overrides'=>'Sovrascritture della lingua','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carica file .mo compilati per sovrascrivere le stringhe del plugin di terze parti per localizzazioni specifiche — ad esempio, una traduzione personalizzata di VikBooking che usa "appartamento" invece di "camera". I file devono seguire la convenzione di denominazione di WordPress: {textdomain}-{locale}.mo (esempio: vikbooking-ca.mo). Sono archiviati nella cartella uploads e sopravvivono agli aggiornamenti del plugin.','Override file uploaded successfully.'=>'File di sovrascrittura caricato con successo.','Override file deleted.'=>'File di sovrascrittura eliminato.','No file was selected.'=>'Nessun file selezionato.','Only .mo files are accepted.'=>'Sono accettati solo file .mo.','The upload failed — please try again.'=>'Il caricamento è fallito — riprova.','Could not save the file. Check that the uploads folder is writable.'=>'Impossibile salvare il file. Verifica che la cartella uploads sia scrivibile.','Invalid filename.'=>'Nome file non valido.','Security check failed — file path is not permitted.'=>'Controllo di sicurezza fallito — percorso del file non consentito.','An unknown error occurred.'=>'Si è verificato un errore sconosciuto.','Text domain / locale'=>'Dominio del testo / locale','Files'=>'File','Size'=>'Dimensione','Delete all files for this override (both .mo and .po)?'=>'Eliminare tutti i file di questa sovrascrittura (sia .mo che .po)?','No override files uploaded yet.'=>'Nessun file di sovrascrittura ancora caricato.','Upload .mo file'=>'Carica file .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accetta solo file .mo compilati. Il nome del file deve seguire il modello {textdomain}-{locale}.mo. Caricare un file con lo stesso nome di uno esistente lo sostituirà.','Upload Override'=>'Carica Sovrascrittura','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copia in Archiviazione Sicura','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate memorizza le sue traduzioni personalizzate in wp-content/languages/loco/ — una posizione che può essere cancellata silenziosamente da un aggiornamento di WP core, reinstallazione del plugin, o se Loco Translate viene rimosso. Copiare i file qui li sposta nella directory Lingua Forge i18n-overrides, che persiste attraverso tutti questi eventi ed è caricata automaticamente ad ogni richiesta.','File copied to safe storage successfully.'=>'File copiato in archiviazione sicura con successo.','Source file not found.'=>'File di origine non trovato.','Could not copy the file. Check that the uploads folder is writable.'=>'Impossibile copiare il file. Verifica che la cartella uploads sia scrivibile.','Invalid file reference.'=>'Riferimento al file non valido.','Type'=>'Tipo','✓ In safe storage'=>'✓ In archiviazione sicura','Copy to safe storage'=>'Copia in archiviazione sicura','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Ancora nessun file personalizzato di Loco Translate trovato. Appaiono qui una volta che salvi una traduzione in Loco Translate.','AI Cache'=>'Cache AI','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge memorizza nella cache le traduzioni generate dall\'IA, le meta descrizioni, gli estratti e i contenuti generati per post, in modo che gli input invariati non riattivino una chiamata API a pagamento. Le voci memorizzate nella cache vengono invalidate automaticamente quando i loro input cambiano. Pulisci manualmente la cache per recuperare spazio nel database, forzare una risincronizzazione dopo aver cambiato provider o modificato i modelli di prompt, o risolvere un problema legato alla cache.','AI cache cleared. %d entry was removed.'=>'Cache AI cancellata. %d voce è stata rimossa.' . "\0" . 'Cache AI cancellata. %d voci sono state rimosse.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Eliminare tutti i risultati AI memorizzati nella cache? Le richieste future attiveranno chiamate API fresche fino a quando la cache non si ricostruisce.','Clear AI Cache'=>'Cancella cache AI','Debug Files'=>'File di debug','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quando il debug logging è abilitato (tramite l\'interruttore qui sotto o definendo LINGUAFORGE_AI_DEBUG in wp-config.php), le funzioni di traduzione e di traduzione dei modelli FSE scrivono le loro richieste AI e le risposte su disco per la risoluzione dei problemi. Usa questa sezione per monitorare quell\'output e cancellarlo una volta ottenuto ciò di cui hai bisogno — i file possono crescere rapidamente su pagine grandi. Configura la directory di destinazione tramite il filtro linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'File di debug cancellati. %d file sono stati rimossi.' . "\0" . 'File di debug cancellati. %d file sono stati rimossi.','Debug logging enabled.'=>'Debug logging abilitato.','Debug logging disabled.'=>'Debug logging disabilitato.','Debug logging'=>'Debug logging','Write AI prompts and responses to disk for troubleshooting'=>'Scrivi richieste e risposte AI su disco per la risoluzione dei problemi','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzato ON dalla costante LINGUAFORGE_AI_DEBUG in wp-config.php. Rimuovi quella riga per controllare questa opzione da qui.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzato OFF dalla costante LINGUAFORGE_AI_DEBUG in wp-config.php. Rimuovi quella riga per controllare questa opzione da qui.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'I file vengono salvati nella directory sottostante. Utile per diagnosticare problemi di traduzione — disattiva una volta ottenuto ciò di cui hai bisogno in modo che i file non si accumulino. Puoi anche forzarlo da wp-config.php con `define( \'LINGUAFORGE_AI_DEBUG\', true );` che sovrascrive l\'interruttore.','Currently:'=>'Attualmente:','✓ Enabled'=>'✓ Abilitato','✗ Disabled'=>'✗ Disabilitato','Directory'=>'Directory','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra con linguaforge_debug_dir per reindirizzare l\'output di debug in una posizione non pubblica.','.txt file(s) in the directory'=>'.txt file(i) nella directory','Save Debug Setting'=>'Salva impostazioni di debug','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Eliminare tutti i file .txt nella directory di debug? La directory stessa rimarrà così le future scritture di debug continueranno a essere salvate correttamente.','Clear Debug Files'=>'Cancella file di debug','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Cache di traduzione per blocco condivisa tra i post. Configura attivazione/disattivazione in Impostazioni → Comportamento. Le statistiche sotto mostrano cosa è attualmente memorizzato nella cache; la cancellazione forza ogni blocco a essere ritradotto alla prossima richiesta (utile dopo l\'aggiornamento dei modelli o per recuperare spazio nel database).','Translation Memory cleared. %d cached block was removed.'=>'Memoria di traduzione cancellata. %d blocco memorizzato nella cache è stato rimosso.' . "\0" . 'Memoria di traduzione cancellata. %d blocchi memorizzati nella cache sono stati rimossi.','Status'=>'Stato','— toggle in Settings → Behavior.'=>'— attivato in Impostazioni → Comportamento.','Cached blocks'=>'Blocchi memorizzati nella cache','Cumulative cache hits'=>'Colpi di cache cumulativi','(avg %.1f hits/block)'=>'(media %.1f colpi/blocco)','Oldest entry'=>'Voce più vecchia','Newest entry'=>'Voce più recente','Approximate size'=>'Dimensione approssimativa','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Cancellare l\'intera memoria di traduzione? Le traduzioni future ricostruiranno la cache man mano che vengono eseguite.','Clear Translation Memory'=>'Cancella memoria di traduzione','Uninstall Behaviour'=>'Disinstalla comportamento','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controlla cosa succede quando un amministratore disinstalla il plugin da Plugins → Plugin installati → Elimina. Le impostazioni del plugin e le cache AI vengono sempre rimosse. Assegnazioni di lingua e relazioni di traduzione sono mantenute di default in modo che una disinstallazione accidentale o una reinstallazione possano riprendere da dove avevano lasciato.','Uninstall setting saved.'=>'Impostazione di disinstallazione salvata.','Delete content data on uninstall'=>'Elimina dati di contenuto alla disinstallazione','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Elimina anche assegnazioni di lingua, relazioni di traduzione, meta descrizioni, glossario e memoria di traduzione quando il plugin viene disinstallato','Warning:'=>'Avviso:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Se selezionato, disinstallando il plugin verranno eliminati definitivamente tutte le assegnazioni di lingua, relazioni di traduzione, meta descrizioni, preset per pagina, il glossario AI e la memoria di traduzione per ogni post di questo sito. Questo non può essere annullato. Lasciare deselezionato a meno che non si rimuova completamente il supporto multilingue dal sito.','Save Uninstall Setting'=>'Salva impostazione di disinstallazione','Router'=>'Router','Primary language saved.'=>'Lingua principale salvata.','Permalink rules flushed successfully.'=>'Regole permalink svuotate con successo.','Primary Language'=>'Lingua principale','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'La lingua principale viene sempre servita alla radice del tuo sito — nessun prefisso URL in modalità percorso, nessun sottodominio di lingua in modalità sottodominio. Tutite le altre lingue usano un prefisso di percorso /lang/ (esempio: example.com/de/) o un sottodominio di lingua (esempio: de.example.com), a seconda dell\'impostazione della struttura URL sottostante.','Primary language'=>'Lingua principale','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Dopo aver cambiato la lingua principale, svuota i permalink (sezione sotto) affinché l\'aggiornamento della struttura URL venga applicato.','URL structure'=>'Struttura URL','Path prefix — example.com/de/'=>'Prefisso del percorso — example.com/it/','Subdomain — de.example.com/'=>'Sottodominio — it.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'La modalità sottodominio richiede che il tuo server web punti tutti i sottodomini di lingua (ad esempio de.example.com) a questa installazione di WordPress. Dopo aver cambiato modalità, aggiorna le regole dei permalink e svuota le cache. Se il tuo URL principale include www (ad esempio www.example.com), usa il filtro lf_base_domain per impostare il dominio apex nudo in modo che i sottodomini siano costruiti correttamente.','Browser language redirect'=>'Reindirizzamento della lingua del browser','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Reindirizza i visitatori alla loro lingua preferita in base all\'intestazione Accept-Language del browser','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quando abilitato, i visitatori alla prima visita senza cookie di lingua e senza prefisso di lingua nell\'URL vengono reindirizzati alla versione linguistica più vicina. Il reindirizzamento viene saltato se la lingua preferita dal browser non è tra le lingue attive del router. Una volta che un visitatore seleziona una lingua tramite il switcher, il cookie ha priorità e l\'intestazione del browser viene ignorata in tutte le visite future.','Save Router Settings'=>'Salva impostazioni del router','Flush Permalinks'=>'Svuota permalink','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Rigenera le regole di riscrittura di WordPress in modo che i prefissi URL, gli slug specifici della lingua e le riscritture degli archivi siano sincronizzati. Necessario dopo aver cambiato la lingua principale o aver aggiunto il supporto per nuove lingue.','Flush Permalink Rules'=>'Svuota regole permalink','Active Languages'=>'Lingue attive','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Lingue attualmente conosciute dal router (derivate dai pacchetti di localizzazione di WordPress installati più la lingua principale). Installa pacchetti di lingua aggiuntivi nella sezione sottostante per rendere disponibili più lingue per il routing e la traduzione.','%d locale pack installed.'=>'%d pacchetto di localizzazione installato.' . "\0" . '%d pacchetti di localizzazione installati.','Install a Language'=>'Installa una lingua','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Scarica e installa un pacchetto di lingua di WordPress direttamente da WordPress.org. Una volta installato, il locale diventa disponibile per il routing URL e il flusso di lavoro di traduzione AI. L\'elenco delle lingue disponibili viene recuperato su richiesta — clicca il pulsante sottostante per caricarlo.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'L\'installazione del pacchetto di lingua è disabilitata su questo server. La costante DISALLOW_FILE_MODS è impostata in wp-config.php. Installa manualmente i pacchetti di lingua tramite WP-CLI: wp language core install de_DE','Load available languages'=>'Carica le lingue disponibili','— select a language —'=>'— seleziona una lingua —','Install'=>'Installa','Language Setup'=>'Configurazione della lingua','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Nessuna lingua secondaria configurata. Installa un pacchetto di lingua sopra per abilitare lo scaffolding del modello.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Seleziona una lingua per gestire i suoi modelli FSE, parti del modello e menu di navigazione.','Forbidden'=>'Vietato','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'L\'installazione della lingua è disabilitata su questo server (DISALLOW_FILE_MODS è impostato).','Invalid locale code.'=>'Codice locale non valido.','Language %s installed successfully.'=>'Lingua %s installata con successo.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Installazione del pacchetto di lingua fallita. La lingua potrebbe essere già installata, il codice locale potrebbe essere errato, o il server potrebbe bloccare le scritture sui file.','Navigations'=>'Navigazioni','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traduzione della navigazione richiede un provider AI attivo. Configura una chiave API nella scheda Chiavi API.','Navigation'=>'Navigazione','Action'=>'Azione','Re-translate'=>'Ritraduci','CPT Block Patterns'=>'Modelli di blocco CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Modelli registrati per tipi di post personalizzati. Usa il pulsante Traduci per produrre una variante linguistica. Il contenuto tradotto viene salvato qui e può essere copiato in qualsiasi post CPT dall\'inseritore di modelli dell\'editor a blocchi o usato come punto di partenza per un Modello Sincronizzato (Blocco Riutilizzabile).','Pattern'=>'Modello','Post Types'=>'Tipi di post','✓ Translation saved'=>'✓ Traduzione salvata','View'=>'Visualizza','Template Parts'=>'Parti del modello','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Copie specifiche della lingua delle parti del modello del tema. Una volta create, i modelli vengono aggiornati per fare riferimento alla parte specifica della lingua.','Part'=>'Parte','Status / Actions'=>'Stato / Azioni','Fix Links'=>'Correggi link','Fix Nav'=>'Correggi navigazione','Create'=>'Crea','Templates'=>'Modelli','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Modelli FSE seminati dal tema attivo. Crea e personalizza nel Modificatore del Sito.','Actions'=>'Azioni','Fix Parts'=>'Correggi parti','Create missing'=>'Creare mancante','Translate all'=>'Traduci tutto','Fix all parts'=>'Correggi tutte le parti','Fix all links'=>'Correggi tutti i link','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Test in corso…','✓ Connection OK'=>'✓ Connessione OK','✗ Failed:'=>'✗ Fallito:','No response from provider — check the error log for details.'=>'Nessuna risposta dal provider — controlla il registro degli errori per i dettagli.','Network error — could not reach the WordPress AJAX endpoint.'=>'Errore di rete — impossibile raggiungere il punto finale AJAX di WordPress.','Loading…'=>'Caricamento…','Installing…'=>'Installazione…','✓ Language installed.'=>'✓ Lingua installata.','✗ Error:'=>'✗ Errore:','Creating…'=>'Creazione…','✓ All templates created.'=>'✓ Tutti i modelli creati.','Some templates could not be created.'=>'Alcuni modelli non sono stati creati.','✓ All parts created.'=>'✓ Tutte le parti create.','Some parts could not be created.'=>'Alcune parti non sono state create.','✓ All translated.'=>'✓ Tutte tradotte.','Some translations failed.'=>'Alcune traduzioni non sono riuscite.','Review carefully — links and slugs not updated.'=>'Revisiona attentamente — link e slug non aggiornati.','Fixing…'=>'Correzione in corso…','✓ Links fixed.'=>'✓ Link corretti.','Some link fixes failed.'=>'Alcune correzioni di link non sono riuscite.','✓ Parts fixed.'=>'✓ Parti corrette.','Some part fixes failed.'=>'Alcune correzioni di parti non sono riuscite.','✓ Nav refs fixed.'=>'✓ Riferimenti di navigazione corretti.','Some nav ref fixes failed.'=>'Alcune correzioni di riferimenti di navigazione non sono riuscite.','✓ Pattern translated.'=>'✓ Modello tradotto.','Pattern translation failed.'=>'Fallimento della traduzione del modello.','Hide'=>'Nascondi','Built-in preset instructions:'=>'Istruzioni predefinite incorporate:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Nessuna istruzione predefinita — ogni funzione AI utilizza le proprie impostazioni di default ottimizzate. Compila il campo Istruzioni prompt personalizzate qui sotto per aggiungere le tue regole a livello di sito.','Settings'=>'Impostazioni','You do not have permission to manage these settings.'=>'Non hai il permesso di gestire queste impostazioni.','Lingua Forge — Settings'=>'Lingua Forge — Impostazioni','Settings saved.'=>'Impostazioni salvate.','Save Settings'=>'Salva impostazioni','Standard'=>'Standard','Technical / Scientific'=>'Tecnico / Scientifico','Legal / Compliance'=>'Legale / Conformità','Creative / Marketing'=>'Creativo / Marketing','Full Article'=>'Articolo completo','Introduction only'=>'Solo introduzione','Structured Outline'=>'Schema strutturato','Generate Content'=>'Genera contenuto','Hints'=>'Suggerimenti','Key points, ideas, or structure to build from…'=>'Punti chiave, idee o struttura da cui partire…','Tone'=>'Tono','Output'=>'Output','Generate Excerpt'=>'Genera estratto','Generate Meta Description'=>'Genera meta descrizione','Translate Content'=>'Traduci contenuto','Mode'=>'Modo','Full post'=>'Post completo','Translate chunk'=>'Traduci blocco','Target Language'=>'Lingua di destinazione','Text to translate'=>'Testo da tradurre','Paste a footnote, sentence, or any snippet here…'=>'Incolla una nota a piè di pagina, una frase o qualsiasi frammento qui…','Also generate meta description'=>'Genera anche meta descrizione','Translated Names'=>'Nomi tradotti','Name displayed in this language. Leave empty to use the source name.'=>'Nome visualizzato in questa lingua. Lascia vuoto per us